void sort_calendar(date d[],int n){
for(int i=0;i<n;i++)
for(int j=n-1;j>i;j--)
if(d[j].year<d[j-1].year)
swap(d[j],d[j-1]);
else
if(d[j].year==d[j-1].year)
if(d[j].month<d[j-1].month)
swap(d[j],d[j-1]);
else
if(d[j].month==d[j-1].month)
if(d[j].day<d[j-1].day)
swap(d[j],d[j-1]);
}//交换函数定义略
