A卷第一题(BY LuHaozhe)
#include <iostream>
using namespace std;
class Complex {
int shi;
int xu;
public:
Complex() {
shi = 0;
xu = 0;
}
void input(int a,int b) {
shi = a;
xu = b;
}
friend Complex operator+(Complex& a, Complex& b)
{
Complex temp;
temp.shi = a.shi + b.shi;
temp.xu = a.xu + b.xu;
return temp;
}
friend Complex operator-(Complex& a, Complex& b)
{
Complex temp;
temp.shi = a.shi - b.shi;
temp.xu = a.xu - b.xu;
return temp;
}
friend Complex operator*(Complex& a, Complex& b)
{
Complex temp;

temp.shi = a.shi * b.shi - a.xu * b.xu;
temp.xu = a.shi * b.xu + b.shi * a.xu;
return temp;
}
void output() {
if (shi == 0) {
if (xu == 0) {
cout << "0" << endl;
}
else {
cout << xu << "i" << endl;
}
}
else {
if (xu == 0) {
cout << shi << endl;
}
else {
if (xu > 0) {
cout << shi << "+" << xu << "i" << endl;
}
else {
cout << shi << xu <<"i" <<endl;
}
}
}
}
};
int main() {
int a1, a2, b1, b2;
cin >> a1 >> a2 >> b1 >> b2;
Complex com1;

Complex com2;
Complex com3;
Complex com4;
Complex com5;
com1.input(a1, a2);
com2.input(b1, b2);
com3 = com1 + com2;
com3.output();
com4 = com1 - com2;
com4.output();
com5 = com1 * com2;
com5.output();
return 0;
}
