A卷第三题(BY Luhaozhe)
#include<iostream>
#include<string>
using namespace std;
template <class T>
class list {
struct node {
T data;
node* next;
};
node* head;
node* tail;
public:
list() : head(nullptr), tail(nullptr) {}
void Insert(T item) {
node* newNode = new node;
newNode->data = item;
newNode->next = head;
head = newNode;
if (tail == nullptr) {
tail = head;
}

}
void Append(T item) {
node* newNode = new node;
newNode->data = item;
newNode->next = nullptr;
if (tail == nullptr) {
head = tail = newNode;
} else {
tail->next = newNode;
tail = newNode;
}
}
int count() {
int count = 0;
node* current = head;
while (current != nullptr) {
count++;
current = current->next;
}
return count;
}
void htot() {
if (head != nullptr && head != tail) {
node* firstNode = head;
head = head->next;
tail->next = firstNode;
firstNode->next = nullptr;
tail = firstNode;
}
}

void ttoh() {
if (head != nullptr && head != tail) {
node* lastNode = tail;
node* current = head;
while (current->next != tail) {
current = current->next;
}
current->next = nullptr;
tail = current;
lastNode->next = head;
head = lastNode;
}
}
void display() {
if (head == nullptr) {
std::cout << "emptylist";
} else {
node* current = head;
while (current != nullptr) {
std::cout << current->data << " ";
current = current->next;
}
}
std::cout << std::endl;
}
void SortList() {
if (head != nullptr && head != tail) {
node* current = head;
node* index = nullptr;
T temp;

while (current != nullptr) {
index = current->next;
while (index != nullptr) {
if (current->data > index->data) {
temp = current->data;
current->data = index->data;
index->data = temp;
}
index = index->next;
}
current = current->next;
}
display();
}
}
};
int main() {
string listType;
cin >> listType;
int length;
cin >> length;
if (listType == "int") {
list<int> link1;
list<int> link2;
for (int i = 0; i < length; i++) {
int item;
cin >> item;

link1.Append(item);
link2.Insert(item);
}
cout << link1.count() << endl;
link1.display();
link1.ttoh();
link1.display();
cout << link2.count() << endl;
link2.display();
link2.htot();
link2.display();
cout << "Sorted List: ";
link1.SortList();
} else if (listType == "char")
{ list<int> link1;
list<int> link2;
for (int i = 0; i < length; i++) {
char item;
cin >> item;
link1.Append(item);
link2.Insert(item);
}
cout << link1.count() << endl;
link1.display();
link1.ttoh();

link1.display();
cout << link2.count() << endl;
link2.display();
link2.htot();
link2.display();
cout << "Sorted List: ";
link1.SortList();
}
return 0;
}

比如“学生”这个类,可以有姓名、成绩等成员变量,也可以有打印信息、计算等级等成员函数。
• 类名是标识符,命名规则和变量名类似。
• 类由成员变量和成员函数组成。
• 类定义结束后必须加分号“;”。
• 成员函数如果写在类外,函数名前必须加“类名::”。
易错提醒:很多改错题会故意漏掉类定义后的分号,或漏掉类外成员函数定义的“类名::”。
#include <iostream>
using namespace std;
class Student { // 类定义
private:
string name;
int score;
public:
void setInfo(string n, int s); // 类内声明
void print();
}; // 注意:类定义后必须有分号
void Student::setInfo(string n, int s) { // 类外定义要写 Student::
name = n;
score = s;
}
void Student::print() {
cout << name << " " << score << endl;
}
int main() {
Student stu;
stu.setInfo("Li", 90);
stu.print();
return 0;
}
2. 类成员访问权限:public、private、protected
访问权限决定“谁能直接使用这个成员”。可以把类想成一个房间:public 是公开区域,谁都能进;private 是个人抽
屉,只有类自己能打开;protected 是家族成员区域,类自己和派生类可以访问。
• public:类外可以访问。
• private:默认权限,类外不能访问;非友元、非继承情况下也不能访问。
• protected:类外不能访问,但派生类成员函数可以访问基类 protected 成员。
• 类内不仅指类定义体,也包括类的成员函数体。成员函数可以访问同类对象的 private 成员。
易错提醒:class 默认 private;struct 默认 public。考试中常问“类外能否访问私有成员”。答案通常是不能,除非通过公有成员函
数或友元。

问同类对象的 private 成员。
易错提醒:class 默认 private;struct 默认 public。考试中常问“类外能否访问私有成员”。答案通常是不能,除非通过公有成员函
数或友元。
#include <iostream>
using namespace std;
class A {
private:
int x = 1;
protected:
int y = 2;
public:
int z = 3;
void show() {
cout << x << " " << y << " " << z << endl; // 类内都能访问
}
};
int main() {
A a;
// cout << a.x; // 错:private 类外不能访问

// cout << a.y; // 错:protected 类外不能访问
cout << a.z << endl; // 对:public 类外能访问
a.show();
return 0;
}
3. 构造函数与析构函数
构造函数用于“对象出生时初始化”,析构函数用于“对象死亡时清理资源”。构造函数名与类名相同,没有返回值;
析构函数名前加 ~,也没有返回值,且一个类只能有一个析构函数。
• 对象创建时自动调用构造函数。
• 对象生命周期结束时自动调用析构函数。
• 构造顺序:成员对象和基类先构造,派生类后构造;析构顺序相反。
• 如果类中有 const 成员或引用成员,通常必须用初始化列表初始化。
#include <iostream>
using namespace std;
class Point {
private:
int x, y;
public:
Point() : x(0), y(0) { // 无参构造
cout << "无参构造" << endl;
}
Point(int a, int b) : x(a), y(b) { // 有参构造,初始化列表
cout << "有参构造" << endl;
}
~Point() {
cout << "析构" << endl;
}
void show() { cout << x << "," << y << endl; }
};
int main() {
Point p1; // 调用无参构造
Point p2(3, 4); // 调用有参构造
p2.show();
return 0;
}
4. 初始化列表、拷⻉构造函数、委托构造函数
初始化列表写在构造函数参数表后面,用冒号开头。它不是“赋值”,而是对象刚创建时直接初始化,因此更高效,
也能初始化 const 成员、引用成员和对象成员。
• 拷⻉构造函数通常形式:ClassName(const ClassName& obj)。当用已有对象初始化新对象、函数按值传参、函数按
值返回对象时可能被调用。
• 委托构造函数是一个构造函数调用同类另一个构造函数,减少重复代码。
#include <iostream>
using namespace std;

函数按值传参、函数按
值返回对象时可能被调用。
• 委托构造函数是一个构造函数调用同类另一个构造函数,减少重复代码。
#include <iostream>
using namespace std;
class Box {
private: m
const int id; // const 成员必须初始化列表初始化
int value;
public:
Box() : Box(0, 0) {} // 委托构造:调用 Box(int,int)
Box(int i, int v) : id(i), value(v) {}
Box(const Box& b) : id(b.id), value(b.value) { // 拷⻉构造
cout << "copy constructor" << endl;
}
void show() const { cout << id << ":" << value << endl; }
};
int main() {
Box b1(1, 100);
Box b2 = b1; // 用已有对象初始化新对象,调用拷⻉构造
b2.show();

return 0;
}
易错提醒:“对象初始化”和“对象赋值”不是一回事:Box b2 = b1 是初始化,通常调用拷⻉构造;b2 = b1 是赋值,调用赋值运算
符。
5. 静态成员
静态成员属于“类本身”,不专属于某一个对象。可以把 static 成员理解成全班共享的一块黑板,而普通成员是每个
学生自己的笔记本。
• 静态数据成员通常要在类外定义一次。
• 静态成员函数没有 this 指针,只能直接访问静态成员,不能直接访问普通成员。
• 可以通过类名::成员访问,也可以通过对象访问。推荐用类名::成员。
#include <iostream>
using namespace std;
class Student {
private:
string name;
public:
static int count; // 声明静态数据成员
Student(string n) : name(n) { count++; }
static void showCount() { // 静态成员函数
cout << "学生人数:" << count << endl;
// cout << name; // 错:静态函数不能直接访问普通成员
}
};
int Student::count = 0; // 类外定义并初始化
int main() {
Student a("A"), b("B");
Student::showCount();
return 0;
}
6. 常量成员:const 数据成员与 const 成员函数
常量成员在课件范围中被列为复习内容。const 数据成员一旦初始化后不能改;const 成员函数承诺“不修改对象的普
通数据成员”。
• const 数据成员必须通过初始化列表初始化。
• const 成员函数写法:返回值函数名(参数) const。
• const 对象只能调用 const 成员函数。
#include <iostream>
using namespace std;
class Circle {
private:
const double pi; // const 数据成员
double r;
public:

ream>
using namespace std;
class Circle {
private:
const double pi; // const 数据成员
double r;
public:
Circle(double radius) : pi(3.14159), r(radius) {}
double area() const { // const 成员函数,不修改对象
return pi * r * r;
}
};
int main() {
const Circle c(2.0);
cout << c.area() << endl; // const 对象可以调用 const 成员函数
return 0;
}
7. 友元函数
友元不是类的成员,但被类“授权”,可以访问类的 private 和 protected 成员。它常用于运算符重载,尤其是需要让左
操作数不是当前类对象的情况。

• 在类中用 friend 声明。
• 友元函数通常把类对象作为参数,通过对象访问私有成员。
• 友元破坏封装性,考试中要会写,但实际工程中应谨慎使用。
